/// The API module: the reference generated by `tool/thor docs`, one page
/// per package and one per folder.
library;

import 'package:thor_ui/router.dart';

import '../../core/content/library.dart' show apiPackages;
import 'pages/api_index_page.dart';
import 'pages/api_package_page.dart';
import 'pages/api_topic_page.dart';
import 'pages/api_widget_page.dart';

/// `/api`: the reference of `thor_ui`, the one package an app imports.
final apiIndexRoute = ThorRoute('/api', const ApiIndexPage());

/// A package's reference, `/api/:package`.
final apiPackageRoute = ThorRoute('/api/:package', const ApiPackagePage());

/// One folder of a package's reference, `/api/:package/:folder`.
final apiTopicRoute = ThorRoute('/api/:package/:folder', const ApiTopicPage());

/// One widget of a folder, `/api/:package/:folder/:name`.
final apiWidgetRoute = ThorRoute(
  '/api/:package/:folder/:name',
  const ApiWidgetPage(),
);

/// The reference's first page: the package an app imports.
String get apiHomePath => apiPackageRoute.link({'package': apiPackages.first});

/// Every route of the API reference.
final apiModule = Group(
  children: [apiIndexRoute, apiPackageRoute, apiTopicRoute, apiWidgetRoute],
);
